{
  "type": "object",
  "properties": {
    "type": {
      "const": "placeholder.alpha.vector.function"
    },
    "name": {
      "type": "string",
      "description": "The name of the placeholder function."
    },
    "spec": {
      "type": "string",
      "description": "The specification of the placeholder function."
    },
    "input_schema": {
      "type": "object",
      "properties": {
        "context": {
          "type": "object",
          "properties": {
            "type": {
              "const": "object"
            },
            "description": {
              "anyOf": [
                {
                  "type": "string"
                },
                {
                  "type": "null"
                }
              ],
              "description": "The description of the object input."
            },
            "properties": {
              "type": "object",
              "additionalProperties": {
                "$ref": "InputSchema"
              },
              "description": "The properties of the object input."
            },
            "required": {
              "anyOf": [
                {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                },
                {
                  "type": "null"
                }
              ],
              "description": "The required properties of the object input."
            }
          },
          "required": [
            "type",
            "properties"
          ],
          "description": "The optional context input schema shared across all items."
        },
        "items": {
          "$ref": "InputSchema",
          "description": "The input schema for each item."
        }
      },
      "required": [
        "items"
      ],
      "description": "The input schema for the placeholder vector function."
    },
    "skip": {
      "$ref": "Expression",
      "description": "An expression which evaluates to a boolean indicating whether to skip this task. Receives: `input`."
    },
    "input": {
      "type": "object",
      "properties": {
        "context": {
          "$ref": "Expression",
          "description": "An expression which evaluates to the context input. Receives: `input`."
        },
        "items": {
          "$ref": "Expression",
          "description": "An expression which evaluates to the items input. Receives: `input`."
        }
      },
      "required": [
        "items"
      ],
      "description": "The input expression for the placeholder vector function."
    }
  },
  "required": [
    "type",
    "name",
    "spec",
    "input_schema",
    "input"
  ],
  "description": "A placeholder alpha vector function task expression. Always outputs an equalized vector."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "image_url"
    },
    "image_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "Either a URL of the image or the base64 encoded image data."
        },
        "detail": {
          "anyOf": [
            {
              "enum": [
                "auto",
                "low",
                "high"
              ],
              "description": "Specifies the detail level of the image."
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "url"
      ],
      "description": "The URL of the image and its optional detail level."
    }
  },
  "required": [
    "type",
    "image_url"
  ],
  "description": "An image rich content part."
}

